{
  "sop_id": "SOP-017",
  "title": "Vendor onboarding – working procedure",
  "steps": [
    {
      "step_id": "S1",
      "name": "Open onboarding ticket and assign",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Collect registration form and statutory documents",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Check PAN, GSTIN and MSME status on government portals",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D1",
      "name": "Request bank account validation from Finance (treasury)",
      "role": "Executor",
      "type": "approval"
    },
    {
      "step_id": "D2",
      "name": "Request sanctions, blacklist and conflict-of-interest screening from Legal/Compliance",
      "role": "Executor",
      "type": "approval"
    },
    {
      "step_id": "S4",
      "name": "Assess vendor's capability and quality (questionnaire, references, certificates)",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Assign risk category and confirm payment terms, NDA and code-of-conduct acknowledgement",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Draft vendor master record and submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge review",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "A2",
      "name": "Lead approval",
      "role": "Lead",
      "type": "approval"
    },
    {
      "step_id": "A3",
      "name": "HOD approval and activation",
      "role": "HOD",
      "type": "approval"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "always"
    },
    {
      "stage": "HOD",
      "condition": "always"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Finance (treasury)",
      "item": "Bank account validation",
      "parallel_group": "P1"
    },
    {
      "dep_id": "D2",
      "provider": "Legal/Compliance",
      "item": "Sanctions, blacklist and conflict-of-interest screening",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Required document missing",
    "Incorrect category",
    "Amount mismatch",
    "Wrong quantity"
  ],
  "first_pass_yield_target": 0.85
}
